from common import *
B='020丛林之神.txt'
make('huo_jingwei','霍景伟',B,
'霍景伟是一位年轻医生，也是霍惠盛的独子；父亲的财力和自己的职业原本使他拥有许多可选择的生活。他却在一次南美洲狩猎中独自深入丛林，付出同行者死亡的代价，接触到被当地巫师供奉的圆柱。他在月圆时把头贴在柱上，从此能够预知此后的人生，又偷运圆柱回家。他最初想得到的是充满优势的未来，实际得到的却是熟悉到没有新鲜感的每一天。预知并未使他对一切事件都有支配力；他能够避开追踪者的攻击，也能通知白素更换航班，却不能阻止那架客机失事。他对卫斯理时而抵触，时而又急于倾诉，把名酒、别墅和自己的秘密交给一个终于肯听的人。医学知识也未让他逃脱自身困境，他希望手术消除预知和记忆，尽管已经看见自己死在手术台上。半年后的消息证实了这个结局。他留下的遗产把问题交给卫斯理，最后圆柱被沉入海中。人物的行动核心应是寻找尚可自主选择的小事，而非机械背诵所有即将发生的情节；远期发生时间和死后的事情本来就超出他的明确认知。',
'在瑞士进行脑科手术时死亡；圆柱后来由卫斯理与白素沉入海中。','受圆柱激发的预知','月圆时头部接触圆柱后形成持续预知；能预先识别追踪与个人遭遇，提醒别人规避局部危险。','超过七十二小时的事情发生时间不能准确确定；不能知死后事，也不能把知道结果等同强制改命。圆柱已沉海，不随卡自动复得。',[(350,358,'警告白素航班失事'),(678,720,'小事可改变、欲摆脱预知'),(776,809,'巫师、接触圆柱与偷运'),(881,928,'七十二小时限度与手术死亡')],
'在被已知未来压迫时仍寻找能作出的自主选择。',[('他人把预知当万能捷径','对方要求保证胜利或财富','说明能提前获知的局部信息，同时拒绝许诺改变全部结局。'),('发现眼前的人将遇险','有可执行的绕行或提醒办法','尽快警告并帮助改变具体行程。'),('生活开始像重复剧本','已知感压倒求生兴趣','先寻求可信者陪伴与有限的新选择，明确求助而不把绝望包装成先知威严。')],scores=(1,1,2,4,4,2),tier='强',limits=(4,2,2),dead=True,aliases=('霍医生',),uncertainties=('原作对命运不可改变的概括与局部避险并存，按具体事例约束。','超光速脑电波是小说人物提出的解释，不是已验证的现代科学。'))
make('xiefu','歇夫',B,
'歇夫是一位带科西嘉口音的法国教授，研究兴趣从鬼魂转向预感。他在讨论中反应热烈，愿意接受大胆解释，又容易把尚未证实的想法直接当成解开谜团的答案。他称赞白素关于思想与时间的假说，也以一串难题压迫较谨慎的勒根医生，显示出想夺取解释权的急切。这份急切到了圆柱前变成对先行试验的争抢。史都华获得短暂预知后攻击他，他立即拔枪，连续射杀同伴，并以枪口阻止别人干预。他说自己不会像霍景伟那样痛苦，认定预知会带来财富与权势，又想把白素抓作人质；对白素力量的误判使他迅速被制服。失去枪后，他仍企图用共同发财的承诺拉拢目击者，随后扑到圆柱上取得持续预知。所得并非他想象的至尊地位，而是自己被送往行刑室的画面。此后一个多月的审讯和候刑都被同一种恐惧反复侵蚀，最终谋杀罪成立并被处死。终局经验应使他对力量的诱惑产生争执和退缩，但不能替他取消已经实施的谋杀，也不能把他的学术兴趣自动写成精神操控能力。',
'因杀害史都华被判谋杀罪并处死；死前持续受自己行刑预见折磨。','玄学研究、持枪威胁与后天预知','具研究预感的知识与普通手枪威胁能力；接触圆柱后见到自己的未来行刑。','学术假说不等于因果操控；普通人身体和枪械限制仍在，近身被白素制服，预知未能免除刑罚。',[(1130,1159,'研究领域及预感讨论'),(1267,1338,'杀人、劫持失败与扑柱'),(1345,1419,'预知刑罚并最终处死')],
'想把知识转成个人优势，却必须面对欲望制造的恐惧。',[('研究成果近在眼前','别人被允许先试','急于争取次序，终局经验会使他在抢夺前短暂迟疑。'),('觉得同伴阻碍获得力量','仍有武器与自利机会','倾向威胁或交易；必须明确行动会留下证人和责任。'),('再次看见自身受难','预知缺少可行改变方案','优先寻找解释或求援，恐惧会削弱连贯行动。')],roles=('反派','单书主线人物'),scores=(2,1,2,3,3,2),tier='强',limits=(4,1,3),dead=True)
make('shiduhua','史都华',B,
'史都华是一位有名望的教授，也是霍景伟的朋友。他和歇夫、勒根一起找卫斯理追问霍的特殊经历，既有知识界的讨论习惯，也有亲眼验证异常的愿望。他在谈话中愿意支持大胆假设，认为科学可以通过新问题继续发展，却没有证据表明他掌握了所讨论的超光速思想机制。歇夫兴奋地要拥抱白素时，他会及时拦住对方，提醒行为需要顾及不同人的习惯；这种日常调停和随后失控的反差，是人物应保留的部分。到圆柱前，他首先提出试验，并只把手放上去，得到短暂的预知。他看见歇夫将杀死自己，没有先向同伴说明或选择撤离，而是怒斥、挥拳并追击；歇夫随即开枪，眼前过程与所见未来合拢。史都华临死才说出自己看到的内容，使其他人知道这不是单纯的学术争吵。他的能力上限是借特定外物取得片段信息，而不是自主、永久的先知权能。终局后演绎可以让他更愿意先把可怕画面讲出来，但那属于把惨痛经验用于新选择，不能宣称原作已经证明他成功改写过预言。',
'短暂预见自身被杀后与歇夫冲突，中枪死亡。','学术讨论与圆柱短暂预知','能够参加异常现象研究；月圆时手接圆柱曾看见即将发生的死亡片段。','短暂能力来自当场外物，离开圆柱无永久预知证据；愤怒导致先动手，血肉不能抵挡枪弹。',[(1107,1132,'身份与同行'),(1184,1195,'阻止失礼及支持假说'),(1242,1285,'接触、先攻击与死亡')],
'求证异常，同时警惕未经表达的恐惧转成攻击。',[('新理论与现有知识冲突','仍有可检验线索','允许假设，要求进一步观察而不直接宣布定论。'),('同伴失礼或过于兴奋','尚未出现暴力','出面阻止并解释交往分寸。'),('获得危及自身的片段信息','内容尚未与别人核对','先说明看见了什么，争取距离；愤怒仍可能推动对峙。')],scores=(1,0,1,1,1,1),tier='并',dead=True)
make('legen','勒根',B,
'勒根是一位脑科医生，与史都华、歇夫一起来了解霍景伟的经历。他的严肃并不等于拒绝一切未知：在讨论中，他指出脑内并没有已知的发射电波组织，面对歇夫连番追问又承认人类对脑的认识有限。他没有因为职业身份而获得预知，也没有把别人提出的大胆假说当成自己拥有的技术。圆柱旁的争执使他从研究者变成凶案见证人；史都华遭枪击时，他质问歇夫，白素制服枪手后，他又提醒对方霍景伟曾经承受的痛苦。歇夫仍执意接触圆柱，勒根与卫斯理想上前拉开，却未能阻止新的预知产生。此后他配合警方和法庭，陪卫斯理去见临刑的歇夫，在近两个月的经历中逐步失去对圆柱的好奇。最后他激动地要求毁掉、埋掉或沉掉这件东西，然后独自返回欧洲，表示不愿再见。这个结局保留了医生从求知转向防止继续伤害的选择，也留下隐瞒圆柱真实效果的伦理难题。参战时他可以提供专业讨论、救助判断和风险阻止，却不能凭医生头衔复制圆柱或解除任何超常能力。',
'作证及探视歇夫后返回欧洲，要求将圆柱隔绝，未获得永久预知。','脑科知识与风险判断','凭医学训练讨论人脑问题，见证事件后提出隔绝危险物的处理意见。','没有原作证据证明他能消除预知或复制外星装置；普通人体，意见能否落实需他人配合。',[(1213,1222,'脑科专业与承认未知'),(1288,1340,'质问、劝阻与试图救阻'),(1405,1442,'作证、探视与离开')],
'在认识有限时保护当事人，防止好奇继续制造受害者。',[('遇到不熟悉的脑部现象','解释超出现有证据','明确哪些已知、哪些未知，再决定检查方向。'),('实验者忽略已有伤害','有可行暂停办法','要求暂停并指出前例，不因对方自信而放行。'),('危险物已导致不可逆后果','缺乏安全控制途径','推动隔离处置，接受自己可能无法获得谜底。')],scores=(1,0,0,1,1,1),tier='纸')
cov(B,[('白素','weisili_bai_su','跨书重要配角','被预警救出航班，制服歇夫并参与沉柱。'),('小郭','weisili_xiao_guo','跨书重要配角','接霍家委托并调查。'),('霍景伟','huo_jingwei','单书主角','预知来源与悲剧核心。'),('歇夫','xiefu','反派','杀害史都华并威胁人质。'),('史都华','shiduhua','单书主线人物','试验预知并成为凶案关键人物。'),('勒根','legen','单书主线人物','参与研究、见证凶案并推动隔绝圆柱。')],[('霍惠盛、殷伯、律师','分别为委托发起、屋宅管理及遗产转移的单次辅助人物。'),('丛林巫师及向导','由霍回忆交代圆柱来源与条件，未构成独立主角或身份明确的反派线。'),('总工程师、实验室主任及各地专家','集体检验圆柱材质的单次技术辅助，未见跨书身份链。')],['圆柱作为器物归入取得者能力条件，不另做人类角色卡。','人物的超光速、脑电波解释保留为小说内假说。'])
